#!/usr/bin/env python3
"""Inspect primary API/manual pages already downloaded, without execution."""
from html.parser import HTMLParser
from pathlib import Path
class Text(HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts = []
    def handle_data(self, data):
        self.parts.append(data)
base = Path(__file__).resolve().parent
for name in ['gnu', 'clock', 'local', 'utc']:
    p = Text()
    p.feed((base / (name + '.html')).read_text())
    text = ' '.join(' '.join(p.parts).split())
    print(name, text)
